WITH latest AS (SELECT * FROM store_sales QUALIFY ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY units DESC NULLS FIRST, id) = 1) SELECT CASE WHEN revenue >= 4400 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, ROUND(AVG(revenue), 2) AS avg_revenue, COUNT(*) AS cnt, AVG(revenue) AS avg_revenue_2, CORR(units, revenue) AS corr_units_revenue, ROUND(AVG(units), 2) AS avg_units, COUNT(DISTINCT id) AS distinct_ids, GROUPING(CASE WHEN revenue >= 4400 THEN 'PREMIUM' ELSE 'STANDARD' END) AS gid FROM latest GROUP BY CUBE (CASE WHEN revenue >= 4400 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING cnt > 1 ORDER BY avg_revenue_2 NULLS LAST;
